ases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "李继曮", "aliases": ["李繼曮", "李继严", "李繼嚴", "李从曮", "李從曮", "李从严", "李從嚴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光二年条所见人物：李继曮。", "biography": null, "status": "draft", "id": "bc5b776d-9d3a-5767-b334-41720016d9eb"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "段凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明六年条所见人物：段凝。", "biography": null, "status": "draft", "id": "a61490df-1dae-516e-8c17-6a518358fb80"}, {"name": "董璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：董璋。", "biography": null, "status": "draft", "id": "ecbba4d7-b26a-5c43-ad24-180221fafb2b"}, {"name": "王正言", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明元年条所见人物：王正言。", "biography": null, "status": "draft", "id": "b26e6cf6-b408-51ea-9756-2b58df5fa3ef"}, {"name": "符存审", "aliases": ["李存审", "符存"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：符存审。", "biography": null, "status": "draft", "id": "5cb2699c-0840-5cde-b42a-ad5f2eef0a71"}, {"name": "李存渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271龙德二年条所见人物：李存渥。", "biography": null, "status": "draft", "id": "fa7ae3e0-5506-5cef-b177-e295c49f8d36"}, {"name": "李继岌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：李继岌。", "biography": null, "status": "draft", "id": "d160654e-338c-57b